mapper.select:
SELECT pt.TERMS_ID as termsId, pt.TERMS_CODE as termsCode, pt.TERMS_NAME as termsName, pt.SUPPLIER_ID as supplierId, s.SUPPLIER_NAME as supplierName, pt.PAYMENT_DAYS as paymentDays, pt.DISCOUNT_DAYS as discountDays, pt.DISCOUNT_RATE as discountRate, pt.STATUS as status, CASE pt.STATUS WHEN 1 THEN '启用' WHEN 0 THEN '停用' ELSE '未知' END as statusName, pt.BOOK_ID as bookId, pt.TENANT_ID as tenantId, pt.CREATE_TIME as createTime, pt.UPDATE_TIME as updateTime, pt.REMARK as remark FROM T_PAYMENT_TERMS pt LEFT JOIN TBL_SUPPLIER s ON s.SUPPLIER_ID = pt.SUPPLIER_ID WHERE pt.IS_DELETED = 0
AND pt.TERMS_CODE LIKE '%' || #{param.termsCode} || '%'
AND pt.TERMS_NAME LIKE '%' || #{param.termsName} || '%'
AND pt.STATUS = #{param.status}
AND pt.TENANT_ID = #{param.tenantId}
AND pt.BOOK_ID = #{param.bookId}
ORDER BY pt.CREATE_TIME DESC

SELECT COUNT(1)
FROM T_PAYMENT_TERMS
WHERE IS_DELETED = 0
    AND TERMS_CODE = #{termsCode}
    AND TENANT_ID = #{tenantId}

    AND TERMS_ID != #{termsId}
